const shape = new THREE.Shape();
const R = 3.05;
const outerCenterY = -1.55;
const innerCenterY = -2.05;
const startAngleOuter = Math.atan2(0.55, 3);
const endAngleOuter = Math.atan2(0.55, -3);
shape.absarc(0, outerCenterY, R, startAngleOuter, endAngleOuter, false);
shape.lineTo(-3, -1.5);
const startAngleInner = Math.atan2(0.55, -3);
const endAngleInner = Math.atan2(0.55, 3);
shape.absarc(0, innerCenterY, R, startAngleInner, endAngleInner, true);
shape.lineTo(3, -1.0);
const extrudeSettings = { depth: height, bevelEnabled: false, curveSegments: 64 };
const geom = new THREE.ExtrudeGeometry(shape, extrudeSettings);
geom.rotateX(-Math.PI / 2);
geom.translate(0, -height/2, 0);
return geom;

const group = new THREE.Group();

// Back sofa
const backGeo = new THREE.BoxGeometry(width, height, depth * 0.2);
const backMesh = new THREE.Mesh(backGeo);
backMesh.position.set(0, 0, -depth * 0.4);
group.add(backMesh);

// Left sofa
const leftGeo = new THREE.BoxGeometry(width * 0.2, height * 0.6, depth * 0.8);
const leftMesh = new THREE.Mesh(leftGeo);
leftMesh.position.set(-width * 0.4, -height * 0.2, depth * 0.1);
group.add(leftMesh);

// Right sofa
const rightGeo = new THREE.BoxGeometry(width * 0.2, height * 0.6, depth * 0.8);
const rightMesh = new THREE.Mesh(rightGeo);
rightMesh.position.set(width * 0.4, -height * 0.2, depth * 0.1);
group.add(rightMesh);

// Coffee table
const tableGeo = new THREE.BoxGeometry(width * 0.5, height * 0.3, depth * 0.5);
const tableMesh = new THREE.Mesh(tableGeo);
tableMesh.position.set(0, -height * 0.35, depth * 0.1);
group.add(tableMesh);

return group;
